WITH affected AS MATERIALIZED (
 SELECT player_id FROM player_match_stats WHERE match_id=17214 UNION SELECT 2121
), source AS MATERIALIZED (
 SELECT 'after'::text AS model,p.* FROM player_match_stats p WHERE p.player_id IN(SELECT player_id FROM affected)
 UNION ALL SELECT 'before_model',p.* FROM player_match_stats p WHERE player_id=2121
 UNION ALL SELECT 'before_model',p.* FROM jsonb_populate_record(NULL::player_match_stats, '{"id":705437,"goals":0,"kicks":0,"marks":0,"behinds":0,"bounces":0,"club_id":6,"hitouts":0,"tackles":0,"clangers":0,"match_id":17214,"rebounds":0,"contested":0,"disposals":0,"frees_for":0,"handballs":0,"player_id":2121,"source_id":6,"clearances":0,"inside_50s":0,"uncontested":0,"goal_assists":0,"frees_against":0,"jumper_number":"8","career_game_no":126,"one_percenters":0,"contested_marks":0,"import_batch_id":32,"marks_inside_50":0,"source_record_id":"CD_M20260140305|CD_T50|CD_I993799"}'::jsonb) p
), context AS MATERIALIZED (
 SELECT p.*,m.season,m.match_date,m.round_type,m.is_finals_series,c.organization_id,
 CASE WHEN m.result='draw' THEN 'D' WHEN (m.result='home_win')=(m.home_club_id=p.club_id) THEN 'W' ELSE 'L' END AS outcome,
 count(*) OVER(PARTITION BY model,player_id,m.season,club_id) AS club_games
 FROM source p JOIN matches m ON m.id=p.match_id JOIN clubs c ON c.id=p.club_id
), cs AS (SELECT model,player_id,season,club_id,count(*) AS games, count(*) FILTER(WHERE is_finals_series) AS finals, count(*) FILTER(WHERE outcome='W') AS wins, count(*) FILTER(WHERE outcome='D') AS draws, count(*) FILTER(WHERE outcome='L') AS losses, sum(goals) AS goals, sum(behinds) AS behinds, sum(kicks) AS kicks, sum(handballs) AS handballs, sum(disposals) AS disposals, sum(marks) AS marks, sum(tackles) AS tackles, sum(hitouts) AS hitouts, sum(frees_for) AS frees_for, sum(frees_against) AS frees_against, count(disposals) AS disposals_recorded_games,count(tackles) AS tackles_recorded_games,count(hitouts) AS hitouts_recorded_games,count(frees_for) AS frees_recorded_games,bool_or(round_type='grand_final' AND outcome='W') AS is_premier FROM context WHERE season=2026 GROUP BY model,player_id,season,club_id),
ss AS (SELECT model,player_id,season,count(*) AS games, count(*) FILTER(WHERE is_finals_series) AS finals, count(*) FILTER(WHERE outcome='W') AS wins, count(*) FILTER(WHERE outcome='D') AS draws, count(*) FILTER(WHERE outcome='L') AS losses, sum(goals) AS goals, sum(behinds) AS behinds, sum(kicks) AS kicks, sum(handballs) AS handballs, sum(disposals) AS disposals, sum(marks) AS marks, sum(tackles) AS tackles, sum(hitouts) AS hitouts, sum(frees_for) AS frees_for, sum(frees_against) AS frees_against, count(disposals) AS disposals_recorded_games,count(tackles) AS tackles_recorded_games,count(hitouts) AS hitouts_recorded_games,count(frees_for) AS frees_recorded_games,bool_or(round_type='grand_final' AND outcome='W') AS is_premier,count(DISTINCT club_id) AS club_count,(array_agg(club_id ORDER BY club_games DESC,club_id))[1] AS primary_club_id FROM context WHERE season=2026 GROUP BY model,player_id,season),
ssb AS (SELECT ss.*,CASE WHEN EXISTS(SELECT 1 FROM brownlow_season_votes WHERE season=2026) THEN 'complete' WHEN (SELECT status::text FROM seasons WHERE year=2026)='in_progress' THEN 'pending' ELSE 'not_applicable' END AS brownlow_status,
 CASE WHEN EXISTS(SELECT 1 FROM brownlow_season_votes WHERE season=2026) THEN COALESCE((SELECT votes FROM brownlow_season_votes b WHERE b.player_id=ss.player_id AND b.season=2026),0) END AS brownlow_votes FROM ss),
career AS (SELECT model,player_id,count(*) AS games,count(*) FILTER(WHERE is_finals_series) AS finals,count(*) FILTER(WHERE round_type='grand_final' AND outcome='W') AS premierships,count(*) FILTER(WHERE outcome='W') AS wins,count(*) FILTER(WHERE outcome='D') AS draws,count(*) FILTER(WHERE outcome='L') AS losses,COALESCE(sum(goals),0) AS goals, sum(behinds) AS behinds, sum(kicks) AS kicks, sum(handballs) AS handballs, sum(disposals) AS disposals, sum(marks) AS marks, sum(tackles) AS tackles, sum(hitouts) AS hitouts, sum(frees_for) AS frees_for, sum(frees_against) AS frees_against,count(behinds) AS behinds_recorded_games, count(kicks) AS kicks_recorded_games, count(handballs) AS handballs_recorded_games, count(disposals) AS disposals_recorded_games, count(marks) AS marks_recorded_games, count(tackles) AS tackles_recorded_games, count(hitouts) AS hitouts_recorded_games,count(frees_for) AS frees_recorded_games,count(DISTINCT organization_id) AS clubs_played,count(DISTINCT season) AS seasons_played,min(season) AS debut_season,max(season) AS final_season,min(match_date) AS debut_date,max(match_date) AS last_match_date,max(goals) AS best_goals_game,max(disposals) AS best_disposals_game,COALESCE((SELECT sum(b.votes) FROM brownlow_season_votes b WHERE b.player_id=c.player_id),0) AS brownlow_votes,COALESCE((SELECT count(*) FILTER(WHERE is_winner) FROM brownlow_season_votes b WHERE b.player_id=c.player_id),0) AS brownlow_medals FROM context c GROUP BY model,player_id),
clubs AS(SELECT model,player_id,club_id,count(*) AS games,COALESCE(sum(goals),0) AS goals,min(season) AS first_season,max(season) AS last_season,(array_agg(match_id ORDER BY match_date,match_id))[1] AS first_match_id,(array_agg(match_id ORDER BY match_date DESC,match_id DESC))[1] AS last_match_id FROM context GROUP BY model,player_id,club_id),
expected AS(
 SELECT 'player_career_stats' AS family,player_id::text AS key,to_jsonb(c)-'model' AS row FROM career c WHERE model='after'
 UNION ALL SELECT 'player_season_stats',player_id::text||'|'||season,to_jsonb(s)-'model' FROM ssb s WHERE model='after'
 UNION ALL SELECT 'player_club_season_stats',player_id::text||'|'||season||'|'||club_id,to_jsonb(s)-'model' FROM cs s WHERE model='after'
 UNION ALL SELECT 'player_clubs',player_id::text||'|'||club_id,to_jsonb(c)-'model' FROM clubs c WHERE model='after'
),actual AS(
 SELECT 'player_career_stats' AS family,player_id::text AS key,to_jsonb(c)-'rebuilt_at' AS row FROM player_career_stats c WHERE player_id IN(SELECT player_id FROM affected)
 UNION ALL SELECT 'player_season_stats',player_id::text||'|'||season,to_jsonb(s) FROM player_season_stats s WHERE season=2026 AND player_id IN(SELECT player_id FROM affected)
 UNION ALL SELECT 'player_club_season_stats',player_id::text||'|'||season||'|'||club_id,to_jsonb(s) FROM player_club_season_stats s WHERE season=2026 AND player_id IN(SELECT player_id FROM affected)
 UNION ALL SELECT 'player_clubs',player_id::text||'|'||club_id,to_jsonb(c) FROM player_clubs c WHERE player_id IN(SELECT player_id FROM affected)
),diff AS(SELECT COALESCE(e.family,a.family) AS family,COALESCE(e.key,a.key) AS key,e.row AS expected,a.row AS actual FROM expected e FULL JOIN actual a USING(family,key) WHERE e.row IS DISTINCT FROM a.row),
numbered AS(SELECT id,player_id,career_game_no,row_number() OVER(PARTITION BY player_id ORDER BY match_date,match_id) AS expected FROM context WHERE model='after'),
span AS(SELECT player_id,min(season) AS debut_season,max(season) AS final_season FROM context WHERE model='after' GROUP BY player_id),
period_expected AS(SELECT v.club_id,v.period,v.goals,v.behinds,v.points FROM staging.afltables_match a CROSS JOIN LATERAL(VALUES (a.home_club_id,1,a.home_q1_goals,a.home_q1_behinds,a.home_q1_points),(a.home_club_id,2,a.home_q2_goals,a.home_q2_behinds,a.home_q2_points),(a.home_club_id,3,a.home_q3_goals,a.home_q3_behinds,a.home_q3_points),(a.home_club_id,4,a.home_q4_goals,a.home_q4_behinds,a.home_q4_points),(a.away_club_id,1,a.away_q1_goals,a.away_q1_behinds,a.away_q1_points),(a.away_club_id,2,a.away_q2_goals,a.away_q2_behinds,a.away_q2_points),(a.away_club_id,3,a.away_q3_goals,a.away_q3_behinds,a.away_q3_points),(a.away_club_id,4,a.away_q4_goals,a.away_q4_behinds,a.away_q4_points)) v(club_id,period,goals,behinds,points) WHERE a.season=2026 AND a.external_record_id=(SELECT match_key FROM matches WHERE id=17214)),
period_actual AS(SELECT club_id,period,goals,behinds,points FROM match_period_scores WHERE match_id=17214)
SELECT jsonb_build_object(
'snapshot',jsonb_build_object('utc',now() AT TIME ZONE 'UTC','database',current_database(),'user',current_user,'oid',(SELECT oid FROM pg_database WHERE datname=current_database()),'system_id',(SELECT system_identifier::text FROM pg_control_system()),'read_only',current_setting('transaction_read_only'),'isolation',current_setting('transaction_isolation')),
'affected_count',(SELECT count(*) FROM affected),'affected_ids',(SELECT jsonb_agg(player_id ORDER BY player_id) FROM affected),
'reconciliation_counts',(SELECT jsonb_object_agg(family,n) FROM(SELECT family,count(*) AS n FROM expected GROUP BY family)x),
'derived_differences',COALESCE((SELECT jsonb_agg(to_jsonb(d)) FROM diff d),'[]'::jsonb),
'career_number_differences',COALESCE((SELECT jsonb_agg(to_jsonb(n)) FROM numbered n WHERE career_game_no IS DISTINCT FROM expected),'[]'::jsonb),
'player_span_differences',COALESCE((SELECT jsonb_agg(jsonb_build_object('expected',to_jsonb(s),'actual',jsonb_build_object('debut_season',p.debut_season,'final_season',p.final_season))) FROM span s JOIN players p ON p.id=s.player_id WHERE s.debut_season IS DISTINCT FROM p.debut_season OR s.final_season IS DISTINCT FROM p.final_season),'[]'::jsonb),
'period_expected',COALESCE((SELECT jsonb_agg(to_jsonb(p) ORDER BY club_id,period) FROM period_expected p),'[]'::jsonb),
'period_actual',COALESCE((SELECT jsonb_agg(to_jsonb(p) ORDER BY club_id,period) FROM period_actual p),'[]'::jsonb),
'period_full_rows',(SELECT jsonb_agg(to_jsonb(p) ORDER BY club_id,period) FROM match_period_scores p WHERE match_id=17214),
'match',(SELECT to_jsonb(m) FROM matches m WHERE id=17214),
'staged_match',(SELECT to_jsonb(a) FROM staging.afltables_match a WHERE season=2026 AND external_record_id=(SELECT match_key FROM matches WHERE id=17214)),
'club_seasons',(SELECT jsonb_agg(to_jsonb(c) ORDER BY club_id) FROM club_seasons c WHERE season=2026 AND club_id IN(6,16)),
'club_match_totals',(SELECT jsonb_agg(to_jsonb(x) ORDER BY club_id) FROM (SELECT p.club_id,count(*) AS players,sum(p.goals) AS goals,sum(p.behinds) AS behinds,sum(p.kicks) AS kicks,sum(p.handballs) AS handballs,sum(p.disposals) AS disposals,sum(p.marks) AS marks,sum(p.tackles) AS tackles,sum(p.hitouts) AS hitouts,sum(p.frees_for) AS frees_for,sum(p.frees_against) AS frees_against FROM player_match_stats p WHERE match_id=17214 GROUP BY club_id)x),
'staged_club_match_totals',(SELECT jsonb_agg(to_jsonb(x) ORDER BY club_id) FROM (SELECT p.club_id,count(*) AS players,sum(p.goals) AS goals,sum(p.behinds) AS behinds,sum(p.kicks) AS kicks,sum(p.handballs) AS handballs,sum(p.disposals) AS disposals,sum(p.marks) AS marks,sum(p.tackles) AS tackles,sum(p.hitouts) AS hitouts,sum(p.frees_for) AS frees_for,sum(p.frees_against) AS frees_against FROM staging.afltables_player_match p WHERE season=2026 AND match_key=(SELECT match_key FROM matches WHERE id=17214) GROUP BY club_id)x),
'target_expected_career',(SELECT jsonb_agg(to_jsonb(c) ORDER BY model) FROM career c WHERE player_id=2121),
 'target_expected_season',(SELECT jsonb_agg(to_jsonb(c) ORDER BY model) FROM ssb c WHERE player_id=2121),
 'target_expected_club_season',(SELECT jsonb_agg(to_jsonb(c) ORDER BY model,club_id) FROM cs c WHERE player_id=2121),
 'target_expected_clubs',(SELECT jsonb_agg(to_jsonb(c) ORDER BY model,club_id) FROM clubs c WHERE player_id=2121),
 'target_actual_career',(SELECT to_jsonb(c) FROM player_career_stats c WHERE player_id=2121),
 'all_affected_rebuilt_at',(SELECT jsonb_agg(jsonb_build_object('player_id',player_id,'rebuilt_at',rebuilt_at) ORDER BY player_id) FROM player_career_stats WHERE player_id IN(SELECT player_id FROM affected)),
 'edit94',(SELECT to_jsonb(d) FROM data_edits d WHERE id=94),'authority93',(SELECT to_jsonb(o) FROM data_overrides o WHERE id=93),
 'write_attempted',false)::text;
